// Initialize context with first search results
const input = $input.item.json;

const firstResults = input.results || [];
const totalFound = input.total_found || 0;
const avgScore = input.avg_score || 0;


// Initialize search history
const searchHistory = [{
  iteration: 1,
  reasoning: $('Parse Claude Response1').first().json.reasoning,
  search_params: $('Parse Claude Response1').first().json.search_request,
  total_found: totalFound,
  avg_score: avgScore
}];


return {
  json: {
    iteration_count: 1,
    max_iterations: 5,

    search_history: searchHistory,

    accumulated_results: firstResults,

  }
};

// Loop Manager
const input = $input.item.json;

// Increment iteration
const nextIteration = input.iteration_count + 1;
const shouldContinue = nextIteration <= input.max_iterations;

return {
  json: {
    iteration_count: nextIteration,
    should_continue: shouldContinue,

    search_history: input.search_history,
    accumulated_results: input.accumulated_results,

    max_iterations: input.max_iterations,
    user_query: $('Code in JavaScript1').first().json.user_query,
    chat_id: $('Code in JavaScript1').first().json.chat_id,
    current_date: $('Code in JavaScript1').first().json.current_date
  }
};

// Берём ответ от предыдущей ноды (Anthropic)
const response = $input.item.json;

// Пытаемся достать текст из контента
let content = response.content?.[0]?.text || "{}";

// 1) Убираем обёртки типа ```json ... ```
content = content.replace(/```[a-zA-Z]*\s*([\s\S]*?)```/g, "$1");

// 2) Убираем ВСЕ управляющие символы (включая \n, \r, \t)
// Это сделает JSON "однострочным", но зато парсер не сломается
content = content.replace(/[\u0000-\u001F\u007F]/g, "");

// 3) Пытаемся распарсить
let decision;

try {
  decision = JSON.parse(content);
} catch (e) {
  // Если модель вернула текст вокруг JSON — попробуем вырезать первую "{"..."}"
  const jsonMatch = content.match(/\{[\s\S]*\}/);
  if (jsonMatch) {
    const safeMatch = jsonMatch[0].replace(/[\u0000-\u001F\u007F]/g, "");
    try {
      decision = JSON.parse(safeMatch);
    } catch (e2) {
      throw new Error("Could not parse JSON after cleaning: " + safeMatch);
    }
  } else {
    throw new Error("Could not find JSON object in content: " + content);
  }
}

// 4) Валидация action
if (!["search", "answer"].includes(decision.action)) {
  throw new Error("Invalid action: " + decision.action);
}

// 5) Возвращаем нормализованный результат
return {
  json: {
    action: decision.action,
    reasoning: decision.reasoning || null,
    search_request: decision.search_request || null,
  },
};

// Update context with new results
const input = $input.item.json;

const newResults = input.results || [];
const totalFound = input.total_found || 0;
const avgScore = input.avg_score || 0;

const searchHistory = $('Loop Manager').first().json.search_history || [];
const accumulatedResults = $('Loop Manager').first().json.accumulated_results || [];


// Add to history
searchHistory.push({
  iteration: $('Loop Manager').first().json.iteration_count,
  reasoning: $('Parse Decision').first().json.reasoning,
  search_params: $('Parse Decision').first().json.search_request,
  total_found: totalFound,
  avg_score: avgScore
});

// Accumulate results with deduplication
const combined = [...accumulatedResults];
newResults.forEach(result => {
  const identifier = result.chunk_text || result.summary || '';
  const exists = combined.some(r => {
    const existingId = r.chunk_text || r.summary || '';
    return r.call_id === result.call_id && existingId === identifier;
  });
  if (!exists) {
    combined.push(result);
  }
});

// Update found_call_ids
const foundCallIds = combined
  .filter(r => r.score > 0.4)
  .map(r => r.call_id)
  .filter((id, index, self) => self.indexOf(id) === index);

return {
  json: {

    iteration_count: $('Loop Manager').first().json.iteration_count,     // done
    max_iterations: $('Initialize Context').first().json.max_iterations, // done


    search_history: searchHistory,
    accumulated_results: combined,
  }
};

