// Parse Claude response
const response = $input.item.json;
const content = response.content?.[0]?.text || '{}';

// Extract JSON from Claude's response
let searchParams;
try {
  // Try to parse directly
  searchParams = JSON.parse(content);
} catch (e) {
  // If failed, try to extract JSON from markdown code blocks
  const jsonMatch = content.match(/```json\s*([\s\S]*?)```/) || content.match(/```\s*([\s\S]*?)```/);
  if (jsonMatch) {
    searchParams = JSON.parse(jsonMatch[1]);
  } else {
    searchParams = JSON.parse(content);
  }
}

return {
  json: {
    ...$input.item.json,
    reasoning: searchParams.reasoning,
    search_request: searchParams.search_request
  }
};

// Extract answer from Claude response
const response = $input.item.json;
const answer = response.content?.[0]?.text || 'Ошибка генерации ответа';

return {
  json: {
    ...$input.item.json,
    final_answer: answer
  }
};

const messageText = $input.item.json.message?.text || '';
const chatId = $input.item.json.message?.chat?.id || 0;
const currentDate = new Date().toISOString().split('T')[0]; // YYYY-MM-DD

return {
  json: {
    user_query: messageText,
    chat_id: chatId,
    current_date: currentDate
  }
};
